-- Thread 1 (sort 322): the-vineyard-of-yashar-el-and-the-sovereign-grace-of-the-master-in-sirach-and-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-vineyard-of-yashar-el-and-the-sovereign-grace-of-the-master-in-sirach-and-2-esdras',
       'The vineyard of Yashar''el (Israel) and the sovereign-grace of the master — Sirach (Ecclesiasticus) 24 + Sirach 33 + 2 Esdras 5 + 2 Esdras 9''s wisdom-stream witness to the laborers-in-the-vineyard parable',
       'Matt 20:1-16''s laborers-in-the-vineyard parable — the householder hiring labourers across the day''s hours (first, third, sixth, ninth, eleventh) and-paying the-same-penny-at-sunset — read against the wisdom-stream''s direct articulation of the vineyard-of-Yashar''el (Israel) + the-sovereign-grace-of-the-master-distributing-by-the-master''s-will architecture. The framework reads the parable carefully — the laborers-in-the-vineyard substance is NOT the Reformation grace-vs-merit grammar (which would read the parable as faith-alone-over-against-works-of-Torah, collapsing the kingdom-economy into the inherited-Reformed-antinomian-substance the framework rules-out per Red Line #2 and the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md); the parable''s substance is the kingdom-economy-of-the-Father''s-grace-distributed-by-the-householder''s-will, NOT-against-the-Father''s-Way-of-Torah but-as-the-very-means-by-which-the-Father-brings-the-scattered-home. Five moves: Sirach (Ecclesiasticus) 24:8 names the wisdom-of-Yahuah-planted-in-Ya''aqov (Jacob) and Yashar''el (Israel) — the same vineyard-as-the-covenant-body the prophet Yeshayahu (Isaiah) 5:1-7 names; Sirach 24:12 names the rooted-in-the-honourable-people substance (the natural-and-wild-olive-branches of the olive-tree-of-Yashar''el (Israel) per Red Line #11); Sirach 33:13 names THE direct wisdom-stream verbal-anchor for the sovereign-distribution-by-the-master''s-will the householder''s closing-question at Matt 20:15 articulates — *is it not lawful for me to do what I will with mine own?* The same clay-in-the-potter''s-hand substance Yeshayahu (Isaiah) 64:8 and Yirmeyahu (Jeremiah) 18:6 name; 2 Esdras (4 Ezra) 5:23 names the one-only-vine-the-Father-has-chosen-out-of-all-the-trees-of-the-earth substance (the singular-election-of-the-vineyard-of-Yashar''el (Israel) the prophets and the wisdom-stream cohere on); 2 Esdras 9:22 names the many-perish-but-the-grape-and-the-plant-are-kept substance — the wisdom-stream''s direct articulation of the substance the King''s closing *many be called, but few chosen* at v.16 lands. The historic-redemptive substance the parable carries — early-hired prefiguring Yahudah (Judah) the southern-house-that-retained-the-tribal-identity, eleventh-hour-laborers prefiguring the scattered-seed-of-Yashar''el (Israel) the ten-northern-tribes now-being-gathered-home through-the-King''s-proclamation, the same-penny-of-inheritance ruling-out the murmuring-against-the-late-coming-of-the-scattered-seed-from-any-quarter — coheres at Red Line #11''s ingathering-of-the-paternal-blood-remnant architecture and at the *Grace, the Way, the New Heart, and the Mercy of Depart* completion-of-the-sentence the Reformation cut-in-half.',
       sv.verse_id, ev.verse_id, 'complete_study', 322
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20 AND sv.verse_number = 1
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 20 AND ev.verse_number = 16
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 323): many-be-called-but-few-chosen-in-1-enoch-and-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'many-be-called-but-few-chosen-in-1-enoch-and-2-esdras',
       'Many be called, but few chosen — 1 Enoch 39 + 1 Enoch 48 + 2 Esdras 8''s wisdom-stream witness to Matt 20:16''s cause-and-effect-of-hearing',
       'Matt 20:16''s closing-line of the laborers-parable — *so the last shall be first, and the first last: for many be called, but few chosen* — read against the wisdom-stream''s direct articulation of the cause-and-effect-of-hearing per Red Line #11. The framework reads the substance carefully — the substance is BOTH-AND, not EITHER-OR. The Reformed-monergistic-determinism that would collapse the substance into Father-unilaterally-chooses-without-disposition-walked is read-out by the cause-and-effect-architecture (the substance the citizen-walks is the substance-the-Father-knew-from-the-foundation, and the substance-walked is the substance-walked-by-the-citizen-who-is). The Arminian-libertarian-freedom that would collapse the substance into citizen-chooses-without-the-Father''s-foreknowledge is also read-out (the hearing-reveals-what-was-already-true; the substance-of-disposition is the substance-the-Father-knew-from-the-foundation; the hearing-does-not-create the substance-of-disposition). The *many-called-but-few-chosen* substance is the seal of both substances at once — the broad-call going-out because the sheep-are-scattered, and the *chosen* (Greek *eklektoi*) walking-as-the-citizens-the-Father-has-known-from-before-the-foundation (Hitgalut (Revelation) 13:8, 17:8; John 10:26-27''s *ye believe not, because ye are not of my sheep ... my sheep hear my voice*). Four moves: 1 Enoch 39:1 names the wisdom-stream articulation of the elect-and-holy-children-of-the-earth-who-behold-the-secrets-of-the-heaven substance — the *eklektoi* the King names at v.16 are the same elect-and-holy-children the wisdom-stream names; 1 Enoch 48:1 names the broad-fountain-the-thirsty-drink-from substance — the broad-proclamation-substance that reaches-the-many because the citizens are scattered-among-the-nations; 2 Esdras (4 Ezra) 8:1 names THE direct wisdom-stream verbal-anchor for the world-made-for-many-but-the-world-to-come-for-few substance; 2 Esdras 8:3 names the even-more-pointed *there be many created, but few shall be saved* — the wisdom-stream prefiguring the King''s-own-mouth substance. The framework reads the cluster as the wisdom-stream''s direct corroboration of Red Line #11''s cause-and-effect-of-hearing + post-harvest-sifting architecture — the harvest separates wheat-from-tares (Matt 13:30); the gathered-wheat then passes through a post-harvest-sifting (Yechezk''el (Ezekiel) 20:37-38; Matt 25:32; Luke 3:17); names get-blotted-out at the post-harvest-sifting for lawlessness; the warning is to wheat, not to tares. The *few* the parable names are the wheat-that-bears-fruit-and-is-not-blotted-out, not a Reformed-eternal-security-without-the-walking nor an Arminian-perfectability-by-effort.',
       sv.verse_id, ev.verse_id, 'complete_study', 323
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20 AND sv.verse_number = 16
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 20 AND ev.verse_number = 16
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 324): the-cup-of-suffering-and-the-vindication-of-the-righteous-in-wisdom-of-solomon-and-2-maccabees
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-cup-of-suffering-and-the-vindication-of-the-righteous-in-wisdom-of-solomon-and-2-maccabees',
       'The cup of suffering and the vindication of the righteous — Wisdom of Solomon 3 + 5 + 2 Maccabees 7''s wisdom-stream witness to Matt 20:22-23',
       'Matt 20:22-23''s cup-and-baptism dialogue — *are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with?* + the sons'' confidence-without-comprehension *we are able* + the King''s-confirmation *ye shall drink indeed of my cup, and be baptized with the baptism that I am baptized with* — read against the wisdom-stream''s articulation of the cup-of-suffering and the post-suffering vindication-of-the-righteous. The framework reads the substance carefully — the King drinks-the-cup-of-Yahuah''s-wrath at the substitutionary-substance-level (the Tanakh-cup-of-wrath the prophets carried — Psalm 75:8, Yeshayahu (Isaiah) 51:17, 21-22, Yirmeyahu (Jeremiah) 25:15-16, Yechezk''el (Ezekiel) 23:32-34, Habakkuk 2:16); the sons-of-Zavdai (Zebedee) will-drink-the-cup at the apostolic-mission-cost-level — Ya''aqov (James) the son of Zavdai (Zebedee) killed-with-the-sword by Herodes-Agrippa-I at Acts 12:2 as the first apostolic-martyr; Yochanan (John) walking-the-substance-of-tribulation across the long-apostolic-mission to Patmos (Hitgalut (Revelation) 1:9); the two substances are categorically-distinct, and the framework rules-out any reading that flattens them into one. The cross opens-the-door-home through the Father''s-Way-back-to-the-Father; the cross does NOT cancel-the-curse-system (per the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md). Four moves: Wisdom of Solomon 3:1 names the wisdom-stream articulation of the souls-of-the-righteous-in-the-hand-of-Yahuah substance — the substantial-preservation through the apostolic-mission-cost cup; Wisdom of Solomon 5:1 names the post-suffering vindication-of-the-righteous-man-standing-in-great-boldness-before-the-face-of-such-as-have-afflicted-him substance — the day-of-vindication the wisdom-stream had-named at the prefiguring-register; Wisdom of Solomon 5:15 names the righteous-live-for-evermore + reward-with-Yahuah substance — the eschatological-reward the Father distributes by-the-Father''s-will at the substance the substantial-walking-in-the-Way reveals (NOT the Pharisaic-flesh-merit nor the Reformed-no-condition-on-the-believer); 2 Maccabees 7:37 names THE direct extras-stream verbal-anchor for the substantial-martyrdom — the youngest brother offering-up-body-and-life-for-the-laws-of-the-fathers-and-the-mercy-of-the-nation under-the-tyrant-Antiochus (the seven-Maccabean-brothers'' resurrection-confession at vv.9, 14, 23, 29 the apostolic-cup-of-mission-cost would-rehearse). The framework reads the cluster as the wisdom-stream''s direct corroboration of the architecture the cup-and-baptism dialogue rests upon — the substantial-suffering-walked-through-with-preservation-of-the-soul-in-the-hand-of-Yahuah, the post-suffering-vindication-of-the-righteous, the Father''s-distribution-of-the-reward by-the-Father''s-will.',
       sv.verse_id, ev.verse_id, 'complete_study', 324
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20 AND sv.verse_number = 22
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 20 AND ev.verse_number = 23
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 325): the-son-of-adam-came-to-give-his-life-a-ransom-for-many-in-1-enoch-testaments-and-sirach
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-son-of-adam-came-to-give-his-life-a-ransom-for-many-in-1-enoch-testaments-and-sirach',
       'The Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many — 1 Enoch''s Son-of-Adam Parables (ch 46, 48, 62) + Testaments of the Twelve 94 + Sirach 3 (FRAMEWORK-MAJOR)',
       'Matt 20:25-28''s chapter-pivot — the King''s categorical-inversion *but it shall not be so among you ... whosoever will be great among you, let him be your minister (diakonos); and whosoever will be chief among you, let him be your servant (doulos)* + the framework-major v.28 *even as the Son of Adam came not to be ministered unto, but to minister, and to give his life a ransom for many* — read against the wisdom-stream and pseudepigraphal-stream articulation of the Son-of-Adam-lowly-on-earth-and-glorious-in-heaven + greatness-through-humility architecture. The framework reads the cluster as FRAMEWORK-MAJOR per Red Line #12''s Son-of-Adam-restoration and the *Grace, the Way, the New Heart, and the Mercy of Depart* section of framework-deep.md. The King names himself explicitly as the Tanakh-Suffering-Servant of Yeshayahu (Isaiah) 53 and the *kofer*-ransom-substance of the Torah (Shemot (Exodus) 21:30; 30:12-13, 16; Bamidbar (Numbers) 35:31-33; Psalm 49:6-9; Daniel 9:24-27); the *many* (Greek *pollōn*) reads as the *rabbim* of the Servant-passage — the substantial-multitude the Father''s-Book-of-Life from-the-foundation-of-the-world has named, neither the universalist-collapse nor the limited-atonement-restrictivism but the Three-Categories-architecture the framework reads across the gathering-arc. Five moves: 1 Enoch 46:3 names the wisdom-stream''s direct articulation of the Son-of-Adam-who-hath-righteousness — the named Son-of-Adam in the Parables-of-Enoch the gospels articulate at the gospel-pivot; 1 Enoch 48:2 names the Son-of-Adam-named-before-the-foundation-of-the-world substance — the substantial-ransom was determined by-the-Father from-before-the-foundation (per Hitgalut (Revelation) 13:8''s *Lamb slain from the foundation of the world*); 1 Enoch 62:9 names the eschatological-judgment-and-vindication of the Son-of-Adam — the same Son-of-Adam who-walks-the-substantial-ransom at the first-coming will-walk the substantial-judgment at the second-coming; Testaments of the Twelve 94:5 (Testament of Benjamin) names THE direct extras-stream verbal-anchor for the lowly-on-earth-and-glorious-in-heaven substance — the kenotic-incarnational architecture the King articulates at v.28; Sirach (Ecclesiasticus) 3:18 names the wisdom-stream''s direct articulation of the greater-the-more-humble substance — the inverse-architecture the King names at vv.26-27''s *whosoever will be great among you, let him be your minister.* The framework reads the cluster as the wisdom-stream and pseudepigraphal-stream''s direct corroboration of the Son-of-Adam-came-not-to-be-ministered-unto-but-to-minister-and-give-his-life-a-ransom-for-many architecture; the substance is the same-substance through-the-wisdom-stream and-through-the-King and-through-the-apostolic-witness (Philippians 2:6-11''s *made himself of no reputation, and took upon him the form of a servant*; 1 Timothy 2:5-6''s *who gave himself a ransom (antilytron) for all*; Hebrews 9:11-15''s *by his own blood he entered in once into the holy place, having obtained eternal redemption*; 1 Peter 1:18-19''s *redeemed ... with the precious blood of Messiah (Christ)*; Hitgalut (Revelation) 5:9''s *thou wast slain, and hast redeemed us to Elohim (God) by thy blood out of every kindred, and tongue, and people, and nation*). The framework reads the substance in continuity with the cross-opens-the-door-home-without-cancelling-the-curse-system architecture per the *Grace, the Way, the New Heart, and the Mercy of Depart* section — the cup-the-King-drinks opens-the-door-to-the-new-heart-substance the Spirit causes-the-disciple-to-walk-in (Yechezk''el (Ezekiel) 36:26-27; Yirmeyahu (Jeremiah) 31:31-34); the cross does NOT cancel-the-Torah-substance the Spirit-causes-the-disciple-to-keep.',
       sv.verse_id, ev.verse_id, 'complete_study', 325
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20 AND sv.verse_number = 25
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 20 AND ev.verse_number = 28
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 326): the-davidic-messianic-son-recognized-by-the-marginalized-in-testaments-of-the-twelve
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-davidic-messianic-son-recognized-by-the-marginalized-in-testaments-of-the-twelve',
       'The Davidic-Messianic Son recognized by the marginalized — Testaments of the Twelve Patriarchs 37-38''s star-from-Ya''aqov (Jacob) + Branch-of-Elohim + sceptre-of-the-kingdom witness to Matt 20:29-34',
       'Matt 20:29-34''s closing-scene at Yericho (Jericho) — the two-blind-men sitting by the wayside, hearing-that-Yahusha (Jesus)-passed-by, crying-out *thou Son of David, have mercy on us*, met by the multitude''s-rebuke, crying-the-more, the King-stopping-and-calling-and-asking-and-touching, the immediate-recovery-of-sight, and the closing *they followed him* discipleship-substance — read against the wisdom-stream and pseudepigraphal-stream articulation of the Davidic-Messianic credential at Testaments of the Twelve Patriarchs 37-38. The framework reads the cluster against the seed-war-hearing-pattern operating at the marginalized-substance level — the substance the surrounding-multitude cannot-see is the substance the marginalized-substance walks-into-recognizing; the cause-and-effect-of-hearing per Red Line #11''s reading of John 10:26-27''s *ye believe not, because ye are not of my sheep ... my sheep hear my voice* operates at the substance-level beneath-the-substance-of-physical-sight. Three moves: Testaments of the Twelve 37:5 names the wisdom-stream''s direct articulation of the star-from-Ya''aqov (Jacob) substance — the same Davidic-Messianic credential Bamidbar (Numbers) 24:17''s *there shall come a Star out of Ya''aqov (Jacob), and a Sceptre shall rise out of Yashar''el (Israel)* the prophet Bila''am (Balaam) carried; Testaments of the Twelve 38:4 names the Branch-of-Elohim-Most-High substance — the same righteous-Branch Yirmeyahu (Jeremiah) 23:5-6 names (*I will raise unto David a righteous Branch ... this is his name whereby he shall be called, Yahuah Tsidkenu (THE LORD OUR RIGHTEOUSNESS)*) and Zekharyah (Zechariah) 6:12 names (*behold the man whose name is The BRANCH*); Testaments of the Twelve 38:5 names the sceptre-of-the-kingdom-shining-forth + root-with-stem-arising substance — the Davidic-Messianic credential extended through the wisdom-stream''s prefiguring at the same register as the prophet-witnesses. The framework reads the cluster as the wisdom-stream and pseudepigraphal-stream''s direct corroboration of the Davidic-Messianic-substance the marginalized two-blind-men at Yericho (Jericho) walk-into-recognizing — the substance the Tanakh-prophetic-corpus had named (2 Samuel 7:12-16''s Davidic-covenant; Yeshayahu (Isaiah) 11:1-2, 10''s rod-of-Yishai (Jesse) and root-of-Yishai (Jesse); Yirmeyahu (Jeremiah) 23:5-6''s righteous-Branch; Yechezk''el (Ezekiel) 34:23-24 and 37:24-25''s David-the-servant-king of the restored-twelve-tribes; Bamidbar (Numbers) 24:17''s star-and-sceptre). The marginalized-substance the gospel has been preserving through the Matt 9:27-31 Galilean-two-blind-men, the Matt 15:22 Canaanite-woman, here-at-the-Yericho (Jericho)-two-blind-men, anticipates the Matt 21:9 triumphal-entry *Hoshanna (Hosanna) to the Son of David* and the Matt 22:41-46 King''s-own-question-on-the-Son-of-David — the seed-war-hearing-pattern operates substantially through-the-gospel-account, recognizing-the-Davidic-Messianic-substance the surrounding-system-cannot-see.',
       sv.verse_id, ev.verse_id, 'complete_study', 326
  FROM _s155_xref_lookup sv, _s155_xref_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20 AND sv.verse_number = 29
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 20 AND ev.verse_number = 34
ON CONFLICT (slug) DO NOTHING;

