-- ---------------------------------------------------------------------
-- Verification block.
-- ---------------------------------------------------------------------
DO $verify$
DECLARE
  v_xref_inserted INT;
  v_thread_inserted INT;
  v_member_inserted INT;
BEGIN
  SELECT count(*) INTO v_xref_inserted FROM cross_references x
    JOIN _s155_xref_lookup sv ON sv.verse_id = x.source_verse_id
   WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 20
     AND x.tier_required = 'extras' AND x.source = 'manual';

  SELECT count(*) INTO v_thread_inserted FROM cross_reference_threads
   WHERE slug IN (
     'the-vineyard-of-yashar-el-and-the-sovereign-grace-of-the-master-in-sirach-and-2-esdras',
     'many-be-called-but-few-chosen-in-1-enoch-and-2-esdras',
     'the-cup-of-suffering-and-the-vindication-of-the-righteous-in-wisdom-of-solomon-and-2-maccabees',
     'the-son-of-adam-came-to-give-his-life-a-ransom-for-many-in-1-enoch-testaments-and-sirach',
     'the-davidic-messianic-son-recognized-by-the-marginalized-in-testaments-of-the-twelve'
   );

  SELECT count(*) INTO v_member_inserted
    FROM cross_reference_thread_members m
    JOIN cross_reference_threads t ON t.id = m.thread_id
   WHERE t.slug IN (
     'the-vineyard-of-yashar-el-and-the-sovereign-grace-of-the-master-in-sirach-and-2-esdras',
     'many-be-called-but-few-chosen-in-1-enoch-and-2-esdras',
     'the-cup-of-suffering-and-the-vindication-of-the-righteous-in-wisdom-of-solomon-and-2-maccabees',
     'the-son-of-adam-came-to-give-his-life-a-ransom-for-many-in-1-enoch-testaments-and-sirach',
     'the-davidic-messianic-son-recognized-by-the-marginalized-in-testaments-of-the-twelve'
   );

  RAISE NOTICE 'S155 Matt 20 verify: extras xrefs from canon/matthew/20 = %, threads = %, members = %',
    v_xref_inserted, v_thread_inserted, v_member_inserted;

  IF v_thread_inserted <> 5 THEN
    RAISE EXCEPTION 'Expected 5 threads inserted; got %', v_thread_inserted;
  END IF;
  IF v_xref_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 Matt-20 extras xrefs; got %', v_xref_inserted;
  END IF;
  IF v_member_inserted < 21 THEN
    RAISE EXCEPTION 'Expected at least 21 thread members; got %', v_member_inserted;
  END IF;
END;
$verify$;

COMMIT;
